import {loadLocalModel} from './ai/load.js';
const $=id=>document.getElementById(id);
const stages=[['Learn the farmer’s intent.','English and Portuguese examples teach a focused model to recognize six actions: offer, compare, correct, cancel, help and other. Training happens away from the phone.'],['Keep 4,000 useful language features.','Character patterns of three to five letters help recognize short and imperfect messages. The vocabulary is capped at 4,000 features so the inference model stays small.'],['Store 24,000 learned weights.','Six intents × 4,000 features = 24,000 values. Exported as 32-bit floating-point weights, they occupy 96,000 bytes. This is a directly trained compact classifier, not a compressed general language model.'],['Pack only what inference needs.','Weights: 96,000 bytes. Vocabulary: 28,680 bytes. Metadata: 917 bytes. Total model pack: 125,597 bytes. Training libraries and datasets stay off the phone; a small JavaScript runtime reads the exported assets.'],['Cache it inside the companion.','The first online download stores the app and model. After loading, prediction is local: normalize the message, match character features, score intents and ask for clarification when needed. No network call is required for prediction.']];
let animation=null,model=null,lastPrediction=null,database=null;
function showCompact(){const i=Number($('compact').value);$('compact-label').textContent=['Language examples','4,000 features','24,000 weights','125,597-byte model','On-device inference'][i];$('model-step').textContent=`STEP ${i+1} / 5`;$('model-title').textContent=stages[i][0];$('model-copy').textContent=stages[i][1];document.querySelector('.training').style.transform=`scale(${1-i*.09})`;document.querySelector('.training').style.opacity=String(1-i*.10);document.querySelector('.phone').style.transform=`scale(${.8+i*.05})`;}
for(let i=0;i<60;i++)document.querySelector('.matrix').append(document.createElement('i'));
$('compact').oninput=showCompact;$('next-model').onclick=()=>{$('compact').value=(Number($('compact').value)+1)%5;showCompact()};$('animate').onclick=()=>{if(animation){clearInterval(animation);animation=null;$('animate').textContent='Play the squeeze →';return}$('compact').value=0;showCompact();$('animate').textContent='Pause';animation=setInterval(()=>{const i=Number($('compact').value);if(i===4){clearInterval(animation);animation=null;$('animate').textContent='Play the squeeze →';return}$('compact').value=i+1;showCompact()},1800)};
const offline=[['Download once','The service worker caches the companion and compact AI. Model-file integrity is checked before loading. First-time installation happens with connectivity.'],['Think locally','Inference turns the message into an intent on the device. Structured tools can then ask for missing details, while human review controls what becomes a record.'],['Confirm and save','The farmer reviews and confirms. IndexedDB transactions retain records and drafts after reload. This diagram uses its own separate demo database.'],['Reconnect and review','The product’s outbox retries pending operations with operation IDs and revision checks. Conflicts need review. The preview below illustrates this step without sending anything to the marketplace.']];
function showOffline(i){$('offline-title').textContent=offline[i][0];$('offline-copy').textContent=offline[i][1];document.querySelectorAll('[data-node]').forEach(b=>{b.classList.toggle('current',Number(b.dataset.node)===i);b.setAttribute('aria-pressed',String(Number(b.dataset.node)===i))})}document.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>showOffline(Number(b.dataset.node)));
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});$('model-view').hidden=b.dataset.view!=='model';$('offline-view').hidden=b.dataset.view!=='offline'});
async function openDatabase(){return new Promise((resolve,reject)=>{const r=indexedDB.open('harvestlink-ai-explainer',1);r.onupgradeneeded=()=>r.result.createObjectStore('demo');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function putRecord(value){if(!database)database=await openDatabase();return new Promise((resolve,reject)=>{const t=database.transaction('demo','readwrite');t.objectStore('demo').put(value,'record');t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)})}
async function readRecord(){if(!database)database=await openDatabase();return new Promise((resolve,reject)=>{const t=database.transaction('demo','readonly'),r=t.objectStore('demo').get('record');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function displayRecord(r){$('saved').textContent=r?`Farmer-confirmed demo draft\n${r.message}\nIntent: ${r.intent}\n${r.status}\nSaved: ${new Date(r.savedAt).toLocaleString()}`:'No demo record saved yet.';$('sync').disabled=!r||$('offline-toggle').checked}
$('install').onclick=async()=>{try{$('install').disabled=true;$('load-status').textContent='Loading and checking the compact model…';model=await loadLocalModel();if('serviceWorker'in navigator){await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;}const cache=await caches.open('harvestlink-offline-runtime-v1');await cache.addAll(['./local-ai-demo.html','./local-ai-demo.js','./local-ai-demo.css']);$('load-status').textContent=`AI loaded locally · ${model.modelBytes.toLocaleString()} model bytes. App and model ready for offline use.`;$('predict').disabled=false;$('install').textContent='Local AI ready';showOffline(1)}catch(e){$('load-status').textContent='Could not finish downloading. Connect and try again. '+e.message;$('install').disabled=false}};
$('predict').onclick=()=>{if(!model)return;const message=$('message').value;lastPrediction=model.predict(message);$('prediction').textContent=`Local intent: ${lastPrediction.intent}\nMatched language features: ${lastPrediction.matchedFeatures}\n${lastPrediction.needsClarification?'Next step: ask the farmer to clarify.':'Next step: review the harvest details.'}\nInference used the loaded model; no network request.`;$('save').disabled=!message.trim();showOffline(1)};
$('save').onclick=async()=>{try{if(!lastPrediction)return;const r={message:$('message').value,intent:lastPrediction.intent,savedAt:new Date().toISOString(),status:'Saved on this phone · waiting for reconnect preview',operationId:crypto.randomUUID()};await putRecord(r);displayRecord(r);showOffline(2)}catch(e){$('saved').textContent='Storage could not confirm the save. '+e.message}};
$('message').oninput=()=>{lastPrediction=null;$('save').disabled=true;$('prediction').textContent='Run the AI again to review this changed message.'};
$('offline-toggle').onchange=async()=>{$('install').disabled=$('offline-toggle').checked||Boolean(model);$('load-status').textContent=$('offline-toggle').checked?'Offline preview: use the loaded model and save on this phone. No backend requests are made.':model?'Connected preview: local AI remains on the device.':'Load the model once to begin.';try{displayRecord(await readRecord())}catch(e){$('saved').textContent=e.message}};
$('sync').onclick=async()=>{if($('offline-toggle').checked)return;try{const r=await readRecord();if(!r)return;r.status='Reconnect preview complete · no external order sent';await putRecord(r);displayRecord(r);showOffline(3)}catch(e){$('saved').textContent=e.message}};
showCompact();showOffline(0);readRecord().then(displayRecord).catch(e=>{$('saved').textContent='Phone storage unavailable: '+e.message});
